user = self.session.props.auth.user.userName
kind = self.view.custom.confirm
self.view.custom.confirm = ''
loop = self.view.custom.loop
if kind == 'start':
	ok, msg = cal1615.tunerun.start(loop, self.view.custom.bump, user, self.view.custom.mode)
elif kind == 'apply':
	ok, msg = cal1615.tunerun.apply_suggested(loop, user)
elif kind == 'revert':
	ok, msg = cal1615.tunerun.revert_applied(loop, user)
else:
	msg = ''
self.view.custom.msg = msg
